/bin/bash -lc "menv python - <<'PY'
from hera.analysis import open_run,sdh_onset
r=open_run('data/6'); R=r.col('sr1_X')/(r.col('sr0_X')/-1e6); B=r.col('magnet_field')
for hi,lo,deg in [(6,.3,3),(6,.3,5),(8,.3,5),(10,.3,7),(6,1,3),(6,1,5),(10,1,5)]:
 print('\\nWINDOW',lo,hi,'degree',deg)
 try: print(sdh_onset(R,B,b_hi=hi,b_lo=lo,bg_degree=deg,r_full_scale=5000).summary())
 except ValueError as e: print(e)
PY"

